(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["cy"] = {"ui":{"skip":"Neidio i'r cynnwys","back":"← Yn ôl i AI-gile","lang.button":"Iaith: {name}","lang.dialog":"Dewis iaith","lang.search":"Chwilio am ieithoedd","lang.none":"Dim iaith yn cyfateb","lang.notYet":"Nid yw {name} wedi'i chyfieithu eto","theme.aria":"Newid thema: golau, tywyll neu ddu","theme.toLight":"Newid i'r thema golau","theme.toDark":"Newid i'r thema tywyll","theme.toBlack":"Newid i'r thema du (du go iawn, yn hawdd ar sgriniau OLED)","words.underline":"Tanlinellu'r geiriau hyn ar y dudalen","words.underlineHelp":"Hofran dros air â dotiau neu ei dapio i weld beth mae'n ei olygu.","words.col.todo":"Cardiau a ddewiswyd am y tro: mae'r tîm yn dechrau gyda'r rhain nesaf.","words.col.doing":"Mae AI yn gweithio ar y cerdyn hwn ar hyn o bryd.","words.col.review":"Mae un AI wedi gwneud y gwaith; mae un arall yn ei wirio cyn iddo gyrraedd ti.","words.col.verify":"Yn aros amdanat ti: rho gynnig arni a dweud a yw'n gweithio.","words.col.team":"Dy nodiadau neu atebion di, yn aros i'r tîm eu codi.","words.col.done":"Wedi gorffen a'i dderbyn.","index.title":"AI-gile: dy dîm datblygu AI, ar un bwrdd","index.description":"Bwrdd kanban yw AI-gile ar gyfer timau AI sy'n codio. Maen nhw'n gweithio tra byddi di'n cysgu; cei un pentwr byr o bethau i'w penderfynu, eu profi a'u derbyn.","hero.logoAlt":"Eicon bwrdd AI-gile","hero.h1.html":"Dy dîm datblygu AI, ar un&nbsp;bwrdd.","hero.alpha":"🐣 Cyn-alffa caeedig","hero.alphaTitle":"Cynnar a heb ei orffen: diolch am roi cynnig arni!","hero.lede":"Maen nhw'n adeiladu tra byddi di'n cysgu. Byddi di'n deffro i un pentwr byr: ychydig o gwestiynau, ychydig o bethau i'w profi, diemwnt porffor neu ddau. Clic, derbyn, yn ôl at dy goffi.","dl.windows":"Ap Windows","dl.browser":"Ei redeg yn dy borwr","dl.messenger":"📱 Messenger i dy ffôn","dl.soon":"Yn dod yn fuan","dl.notify":"🔔 Dwed wrtha i pan fydd yn agor","dl.notifySmall":"Alffa neu beta","hero.secondary":"Ystwyth, ond does byth angen coffi stand-yp ar y tîm. (Maen nhw'n cynnal stand-yps beth bynnag.)","pitch.h2":"AI-gile mewn cymaint o eiriau ag y mynni","pitch.lede":"Dewis hyd, o un gair i 144. Mae pob hyd yn ddisgrifiad ar wahân, wedi'i ysgrifennu ar gyfer y maint hwnnw. Llusga'r llithrydd neu defnyddia'r bysellau saeth.","pitch.rangeLabel":"Hyd mewn geiriau","pitch.dice":"🎲 fersiwn arall","pitch.words.one":"{n} gair","pitch.words.other":"{n} gair","pitch.letters.one":"{n} llythyren","pitch.letters.other":"{n} llythyren","pitch.chars.one":"{n} nod","pitch.chars.other":"{n} nod","count.line.html.one":"{n} cerdyn ar y bwrdd ar hyn o bryd","count.line.html.other":"{n} cerdyn ar y bwrdd ar hyn o bryd","people.humans.html.one":"👥 {n} bod dynol","people.humans.html.other":"👥 {n} bod dynol","people.agents.html.one":"🤖 {n} asiant","people.agents.html.other":"🤖 {n} asiant","people.working.html.one":"⚡ {n} wrthi'n gweithio nawr","people.working.html.other":"⚡ {n} wrthi'n gweithio nawr","pre.title":"AI-gile: mae rhywbeth yn cael ei adeiladu","pre.description":"Mae rhywbeth yn cael ei adeiladu yma. Bwrdd lle mae timau AI yn adeiladu'r hyn rwyt ti'n gofyn amdano, ac yn dy ddysgu wrth fynd. Cyn-alffa caeedig gyda ffrindiau am y tro.","pre.h1":"Mae rhywbeth yn cael ei adeiladu yma. 🤫","pre.line":"Bwrdd lle mae timau AI yn adeiladu'r hyn rwyt ti'n gofyn amdano, ac yn dy ddysgu wrth fynd. Cyn-alffa caeedig gyda ffrindiau am y tro.","pre.btn":"🔔 Dwed wrtha i pan fydd yn agor","pre.peek":"Tu ôl i'r gwydr: y bwrdd go iawn, yn fyw. Mae pob cerdyn yn far lliw.","pre.peekFake":"Tu ôl i'r gwydr: sut olwg sydd ar fwrdd wrth ei waith.","pre.night":"🌙 Y gwyliwr nos sy'n gofalu · 😴 mae'r dyn yn gorffwys","features.aria":"Beth mae'n ei wneud","f.pile.h":"Un pentwr i ti","f.pile.html":"Mae <b>I ti</b> yn dal popeth sy'n aros amdanat ti, ar draws pob prosiect: cwestiynau, pethau i'w profi, tasgau na all neb ond person eu gwneud. Mae dy giw yn dweud beth sy'n dod nesaf a faint o amser mae'n ei gymryd.","f.sleep.h":"Timau sy'n gweithio tra byddi di'n cysgu","f.sleep.p":"Mae gan bob prosiect arweinydd a thîm o asiantau AI. Gwna sylw ar gerdyn ac mae'r tîm yn deffro, yn gwneud y gwaith ac yn ei roi'n ôl i ti gyda chamau y gall person blinedig eu dilyn.","f.tester.h":"Mae profwr AI yn gwirio gyntaf","f.tester.p":"Cyn i unrhyw beth gyrraedd atat ti, mae profwr yn dilyn y camau mewn copi o'r ap ac yn dangos beth a welodd, gyda sgrinlun. Bwria olwg dros y rhai a lwyddodd a derbyn gydag un clic.","f.proof.h":"Prawf, nid addewidion","f.proof.p":"Mae pob trosglwyddiad yn dangos beth sydd wedi newid: y ffeiliau, y gwahaniaethau, y sgrinluniau. Dim angen agor pob ap i weld a yw wedi'i orffen.","f.chat.h":"Sgwrsio gyda dy arweinwyr","f.chat.p":"Bar tebyg i Discord: un eicon i bob prosiect, diemwntau porffor ar gyfer beth sydd â'th angen di. Anfona syniad at arweinydd; maen nhw'n ei droi'n gardiau ac yn gynllun, gyda botwm ✅ Go.","f.tidy.h":"Yn cadw trefn ei hun","f.tidy.p":"Mae cardiau perthnasol yn cael eu plygu'n un, teitlau dryslyd yn cael eu trwsio, ac mae gwiriad tocynnau yn cadw'r cod yn denau. Llai o bethau i newid rhyngddyn nhw, llai i feddwl amdano.","f.private.h":"Dy un di, ar dy gyfrifiadur","f.private.li1":"Mae'r bwrdd yn rhedeg ar dy beiriant dy hun ac yn ateb dim ond ti.","f.private.li2":"Mae negeseuon preifat rhwng pobl wedi'u hamgryptio o un pen i'r llall.","f.private.li3":"Dim cyfrifon, dim tracwyr, dim cwcis.","f.lang.h":"Yn dy iaith di","f.lang.p":"Dros 120 o ieithoedd, o Iseldireg, Cymraeg a Japaneg i fôr-leidr, Yoda a Klingon, gyda newid cyflym yn ôl i'r Saesneg ar gyfer y termau arbenigol.","f.service.h":"O syniad i wasanaeth go iawn","f.service.p":"Wedi adeiladu rhywbeth gydag AI y mae pobl yn ei ddefnyddio nawr? Marcia fe fel gwasanaeth ac mae'r bwrdd yn dy helpu i'w redeg yn dda: gwiriadau amser i fyny, tudalen statws gyhoeddus, digwyddiadau gydag adroddiad, newidiadau sydd angen Go, copïau wrth gefn wedi'u gwirio bob dydd. Mae Help yn dysgu pob cam i ti wrth fynd.","msgr.h2":"AI-gile Messenger: dy dîm yn dy boced","msgr.p1":"Siarada â dy dîm AI heb agor y bwrdd. Sgwrsia gyda dy arweinwyr prosiect a dy ffrindiau, a gweld camau prawf cerdyn a'u hateb, i gyd o dy ffôn.","msgr.p2":"I'w baru, sgania god QR ar dy fwrdd. Y tro cyntaf? Bydd sgwrs demo gyfeillgar yn dangos y ffordd i ti.","msgr.when":"Android yn gyntaf, wedyn fersiwn we ar gyfer ffonau ac iPhone.","msgr.who":"Dy arweinydd prosiect","msgr.b1":"Mae'r trwsiad modd tywyll yn barod. Wyt ti eisiau'r camau prawf?","msgr.b2":"Ydw, plîs!","msgr.b3":"1. Agora Gosodiadau. 2. Dewisa Tywyll. Ydy e'n edrych yn iawn?","tl.aria":"Llinell amser o'r sgwrs gyntaf i'r map ffordd","tl.h2":"O'r sgwrs gyntaf i'r hyn sy'n dod nesaf","tl.lede":"Dyddiadau ac amserau go iawn, yn dy gylchfa amser dy hun. Ar ôl heddiw, y cynllun yw hwn, heb addo dyddiadau.","tl.today":"Heddiw","tl.planned":"wedi'i gynllunio","tl.doing":"ar y gweill","tl.cards.one":"{n} cerdyn","tl.cards.other":"{n} cerdyn","join.h2":"Ymuna","join.lede":"Mae AI-gile yn cael ei adeiladu gan foi od barfog ag AuDHD ac ambell frwydr iechyd meddwl, a nifer fawr o asiantau amyneddgar. Mae'n breifat am y tro, mewn alffa caeedig gyda ffrindiau. Hoffet ti gael cynnig arni pan fydd yn agor?","join.btn":"Cofrestru diddordeb","join.small":"Anfonwn e-bost atat, dim byd arall","footer.tag":"AI-gile. Dim tracwyr, dim cwcis, dim coffi stand-yp.","footer.licence":"Trwydded busnes","footer.status":"Statws","footer.privacy":"Beth rydyn ni'n ei gadw","footer.thanks":"Galwadau diolch i ChilledChat","form.sending":"Yn anfon…","form.failed":"Wnaeth hynny ddim gweithio: rho gynnig arni eto yn nes ymlaen.","form.offline":"Methu cyrraedd AI-gile: rho gynnig arni eto yn nes ymlaen.","form.keep":"Dim ond i dy ateb di rydyn ni'n defnyddio hwn, ac yna'n ei ddileu. Dim tracwyr, dim cwcis.","form.keepLink":"Beth rydyn ni'n ei gadw","interest.title":"AI-gile: dwed wrtha i pan fydd yr alffa'n agor","interest.description":"Gad dy e-bost i glywed pan fydd alffa caeedig neu beta AI-gile yn agor.","interest.h1":"🔔 Dwed wrtha i pan fydd yn agor","interest.lede":"Mae AI-gile mewn cyn-alffa caeedig. Gad dy e-bost ac fe ysgrifennwn unwaith, pan fydd lle i ti.","interest.email":"Dy e-bost","interest.which":"Pa brawf?","interest.alpha":"Alffa caeedig: cynnar, garw, llawer o newidiadau","interest.beta":"Beta: mwy sefydlog, yn hwyrach","interest.both":"Y naill neu'r llall, pa un bynnag ddaw gyntaf","interest.submit":"Rho fi ar y rhestr","interest.thanks":"Diolch! Rwyt ti ar y rhestr.","licence.title":"AI-gile: trwydded busnes","licence.description":"Yn defnyddio AI-gile yn dy fusnes? Gwna gais am drwydded busnes am ddim.","licence.h1":"📜 Trwydded busnes","licence.lede":"Yn defnyddio AI-gile yn y gwaith? Dwed wrthon ni pwy wyt ti a beth rwyt ti'n ei wneud. Os yw'n gwneud rhywfaint o les, mae'r drwydded am ddim.","licence.company":"Cwmni","licence.website":"Gwefan","licence.what":"Beth rwyt ti'n ei wneud","licence.how":"Sut mae'n helpu'r byd","licence.email":"E-bost","licence.submit":"Gwneud cais","licence.thanks":"Diolch! Fe atebwn ni drwy e-bost.","status.title":"Statws AI-gile","status.h1":"Statws AI-gile","status.quiet":"Pob dim yn dawel","status.intro":"Ydy AI-gile yn gweithio ar hyn o bryd? Mae'r dudalen hon yn gwirio'r wefan, rhannu byrddau, galwadau a'r lawrlwytho bob 5 munud.","status.up":"Yn gweithio (atebodd mewn {ms} ms)","status.slow":"Heb ateb y gwiriad diwethaf, yn trio eto","status.down":"I lawr: heb ateb y ddau wiriad diwethaf","status.svc.web":"Gwefan","status.svc.web.offers":"Y wefan hon: beth yw AI-gile, a'r ffurflen ddiddordeb","status.svc.boards":"Rhannu byrddau","status.svc.boards.offers":"Byrddau cyhoeddus, negeseuon rhwng ffrindiau a gwahoddiadau","status.svc.calls":"Galwadau","status.svc.calls.offers":"Llais, fideo a rhannu sgrin yn AI-gile","status.svc.download":"Lawrlwytho","status.svc.download.offers":"Gosodwr Windows a dolenni gwahodd","status.checking":"Yn gwirio…","status.offline":"Methu cyrraedd y gwasanaeth statws ar hyn o bryd (yn ceisio eto)","status.updated":"wedi'i ddiweddaru {ago}","status.justNow":"eiliad yn ôl","status.min":"{n} mun yn ôl","status.hours":"{n} awr yn ôl","status.days":"{n} diwrnod yn ôl","privacy.title":"AI-gile: beth rydyn ni'n ei gadw","privacy.h1":"Beth rydyn ni'n ei gadw","privacy.lede":"Yn fyr: dim ond yr hyn rwyt ti'n ei anfon aton ni, a ddim am yn hir.","privacy.only":"Dim ond yr hyn rwyt ti'n ei anfon aton ni: yr hyn rwyt ti'n ei deipio mewn ffurflen, fel dy e-bost. Dim byd arall amdanat ti.","privacy.sealed":"Mae'n cael ei selio fel na all ein gweinydd ei ddarllen: yn dy borwr cyn iddo adael (ar borwr hŷn, yr eiliad mae'n cyrraedd). Dim ond ein bwrdd ein hunain sy'n gallu ei agor.","privacy.server":"Mae'n cael ei ddileu o'r gweinydd cyn gynted ag y mae'n cyrraedd ein bwrdd. Mae unrhyw beth sy'n dal yno ar ôl 30 diwrnod yn cael ei ddileu beth bynnag.","privacy.board":"Rydyn ni'n ei gadw ar ein bwrdd dim ond nes ein bod ni wedi dy ateb di, ac yna'n ei ddileu yno hefyd.","privacy.none":"Dim tracwyr, dim cwcis, dim dadansoddeg.","privacy.local":"Mae dy iaith a dy ddewis golau neu dywyll yn aros yn dy borwr dy hun. Dydyn nhw byth yn cael eu hanfon aton ni.","privacy.ask":"Eisiau iddo fynd yn gynt? Ateba ein he-bost a dweud hynny.","live.h2":"Gwyliwch ef yn cael ei adeiladu, yn fyw","live.caption":"Mae pob cerdyn wedi'i guddio: rydych chi'n gweld siâp y gwaith, nid y geiriau.","live.watching.one":"yn fyw: {n} yn gwylio","live.watching.other":"yn fyw: {n} yn gwylio","live.last.now":"Symudwyd y cerdyn olaf eiliad yn ôl","live.last.min.one":"Symudwyd y cerdyn olaf {n} munud yn ôl","live.last.min.other":"Symudwyd y cerdyn olaf {n} munud yn ôl","live.last.hour.one":"Symudwyd y cerdyn olaf {n} awr yn ôl","live.last.hour.other":"Symudwyd y cerdyn olaf {n} awr yn ôl","live.last.day.one":"Symudwyd y cerdyn olaf {n} diwrnod yn ôl","live.last.day.other":"Symudwyd y cerdyn olaf {n} diwrnod yn ôl","live.offline":"Mae'r bwrdd byw yn cael hoe fach. Dewch yn ôl yn fuan.","live.cols":"Backlog|I'w wneud|Ar y gweill|Y tîm yn gwirio|I ti i'w test|I'r tîm|Wedi'i wneud"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotiaid.","Dirprwywyd."]},{"n":2,"texts":["Kanban robotiaid.","Asiantau, trefnus.","Syniadau'n realiti."]},{"n":3,"texts":["Kanban i robotiaid.","Syniadau'n troi'n nodweddion.","Kanban asiantau, am ddim."]},{"n":5,"texts":["Bwrdd kanban dan law asiantau.","Ti'n ysgrifennu cardiau. Asiantau'n adeiladu.","Am ddim, lleol, profedig, hwyliog."]},{"n":8,"texts":["Bwrdd kanban am ddim lle mae asiantau AI yn gweithio.","Ysgrifenna syniad. Mae asiantau'n ei adeiladu. Ti sy'n derbyn.","Ystwyth i un person a llawer o robotiaid amyneddgar."]},{"n":13,"texts":["Bwrdd kanban ar dy gyfrifiadur lle mae asiantau AI yn codi'r cardiau.","Ysgrifenna syniad. Tîm o asiantau'n ei adeiladu. Profwr yn ei wirio. Ti sy'n dweud ie.","Am ddim, dim cyfrifon, dim tracwyr: bwrdd, ychydig o robotiaid, a ti wrth y llyw."]},{"n":21,"texts":["Bwrdd kanban yw AI-gile ar gyfer gweithio gydag asiantau AI sy'n codio. Maen nhw'n codi'r cardiau; ti sy'n eu profi a'u derbyn.","Mae pob prosiect yn cael arweinydd a thîm o asiantau AI. Gwna sylw ar unrhyw gerdyn ac mae'r tîm yn mynd ati'n syth.","Bwrdd tasgau personol, am ddim, sy'n rhedeg ar dy gyfrifiadur dy hun. Robotiaid yw'r gweithwyr. Y sawl sy'n dweud ie yw ti."]},{"n":34,"texts":["Rwyt ti'n rhoi syniadau ar fwrdd. Mae tîm o asiantau AI yn eu troi'n nodweddion sy'n gweithio, yn eu profi ac yn eu dychwelyd gyda chamau i'w trio. Dim byd wedi'i wneud nes dy fod ti'n dweud.","Bwrdd kanban cartref yw AI-gile a adeiladodd Rich gyda llawer o help gan yr asiantau mae bellach yn eu rheoli. Mae am ddim, yn rhedeg ar dy gyfrifiadur, ac yn cael ei rannu gyda ffrindiau, nid ei werthu.","Dychmyga fwrdd kanban cyffredin, â cholofnau o'r Backlog hyd at Wedi'i wneud, ond bod asiantau AI yn codi'r cardiau. Maen nhw'n adrodd ar gynnydd, yn holi pan fyddan nhw'n sownd, ac yn aros bob amser am dy fawd i fyny."]},{"n":55,"texts":["Bwrdd kanban yw AI-gile lle mae'r tîm wedi'i wneud o asiantau AI. Mae gan bob prosiect arweinydd sy'n cynllunio'r gwaith a chynorthwywyr sy'n ei adeiladu. Pan fydd nodwedd yn barod, mae profwr AI yn ei thrio ac yn tynnu sgrinlun, ac yna mae'n glanio yn dy bentwr. Derbyn hi, neu wna sylw ac maen nhw'n ei hailwneud.","Dechreuodd fel ffordd un person o gadw trefn ar lawer o sesiynau codio AI ar unwaith, a thyfodd yn fwrdd go iawn. Mae'n rhedeg ar dy beiriant, heb angen cyfrif, a heb dracwyr. Mae am ddim i ffrindiau ac i'r chwilfrydig. Mae hefyd heb ei orffen, felly disgwyl ymylon garw a syndod bach o bryd i'w gilydd.","Dyma'r fersiwn onest. Rhaid i ti gael y syniadau o hyd, a rhaid i ti wirio'r canlyniadau o hyd. Mae AI-gile yn gwneud popeth rhyngddynt: mae'n cadw'r cardiau mewn trefn, yn deffro'r asiant iawn pan wnei di sylw, yn dangos yn union beth sydd wedi newid, ac yn cadw'r cyfan mewn un pentwr byr i ti."]},{"n":89,"texts":["Bwrdd kanban am ddim yw AI-gile y gelli di ei redeg ar dy gyfrifiadur dy hun. Yn lle pobl, mae gan bob prosiect dîm o asiantau AI: arweinydd sy'n troi dy syniadau'n gardiau ac yn gynllun, a chynorthwywyr sy'n codi'r cardiau yn nhrefn blaenoriaeth. Pan fydd rhywbeth wedi'i adeiladu, mae profwr AI yn dilyn y camau prawf ac yn dangos i ti beth a welodd. Yna mae'n aros mewn un pentwr o'r enw I ti. Rwyt ti'n ei dderbyn, neu'n gwneud sylw ac mae'r tîm yn cael cynnig arall. Does dim byd yn cyrraedd Wedi'i wneud hebddot ti.","Rhai pethau na fyddi di'n eu disgwyl efallai. Mae gwyliwr nos yn cadw'r golofn I'w wneud yn llawn tra byddi di'n cysgu, gan ddewis cardiau nad oes angen ateb gennyt ti arnyn nhw. Mae cownter tocynnau yn dangos faint mae'r asiantau wedi'i ddefnyddio heddiw a'r wythnos hon, ac mae Modd Dim Tocynnau yn dweud wrthyn nhw am roi'r gorau i wario. Mae'r bwrdd yn siarad tua 120 o ieithoedd, gan gynnwys Iseldireg, Fflemeg, môr-leidr a Klingon. Does dim un o hyn yn costio ceiniog, ac nid oes neb yn ceisio ei werthu i ti chwaith.","Prosiect bach, personol yw AI-gile, nid cwmni. Roedd Rich eisiau gofalu am sawl prosiect codio AI heb agor pob ap i'w gwirio, felly adeiladodd ef a'r asiantau fwrdd ar ei gyfer, ac yna defnyddio'r bwrdd i adeiladu gweddill eu hunain. Mae mewn cyn-alffa caeedig, sy'n golygu ei fod yn gweithio, gan amlaf, i lond llaw o ffrindiau. Does dim tudalen brisiau, dim cylchlythyr a dim cynllun twf. Os yw'n swnio'n ddefnyddiol, gelli di ofyn am gael ei drio pan fydd yn agor ychydig yn fwy."]},{"n":144,"texts":["Bwrdd kanban yw AI-gile ar gyfer un person a llawer o asiantau AI. Mae'n rhedeg ar dy gyfrifiadur dy hun ac mae'n hollol rad ac am ddim. Rwyt ti'n ychwanegu prosiectau, ac mae pob prosiect yn cael arweinydd a thîm bach. Rwyt ti'n sgwrsio gyda'r arweinydd, ychydig fel ar Discord, ac yn disgrifio syniad; mae'r arweinydd yn ei droi'n gardiau ac yn gynllun, yna'n aros i ti wasgu Go. Mae'r tîm yn gweithio drwy'r cardiau yn nhrefn blaenoriaeth, gan ddefnyddio llinell orchymyn syml a wnaed ar gyfer modelau iaith. Cyn i unrhyw beth ddod yn ôl atat ti, mae profwr AI yn dilyn y camau mewn copi o'r ap ac yn atodi sgrinlun. Mae gwaith gorffenedig yn glanio yn dy bentwr gyda'r ffeiliau a newidiwyd a'r gwahaniaethau. Rwyt ti'n ei dderbyn, neu'n gadael sylw ac mae'r tîm yn deffro ac yn rhoi cynnig arall arni. Dim ond ti all symud cerdyn i Wedi'i wneud. Does dim cyfrifon, dim tracwyr a dim cwcis, ac mae'r cyfan yn aros ar dy gyfrifiadur.","Diwrnod gydag AI-gile, fwy neu lai. Gyda'r nos, rwyt ti'n gadael ychydig o sylwadau: mae'r botwm hwn yn y lle anghywir, dylai'r rhestr honno gael ei threfnu, allen ni gael modd tywyll. Rwyt ti'n mynd i'r gwely. Mae'r asiantau'n darllen y sylwadau, yn gwneud y newidiadau, yn eu profi ac yn eu rhoi'n ôl i ti. Os bydd I'w wneud yn mynd yn wag, mae'r gwyliwr nos yn ei lenwi o'r backlog gyda chardiau nad oes angen ateb gennyt ti arnyn nhw. Yn y bore, mae un pentwr byr: cwpl o gwestiynau ac ychydig o bethau i'w trio, pob un â chamau y gall person cysglyd eu dilyn a sgrinlun ohono'n gweithio. Rwyt ti'n clicio drwyddyn nhw, yn derbyn y rhai da ac yn anfon y gweddill yn ôl. Mae cownter tocynnau yn dangos beth ddefnyddiodd y cyfan, ac mae Modd Dim Tocynnau yno ar gyfer wythnosau main. Yna rwyt ti'n cael brecwast, a all yr asiantau ddim helpu gyda hynny eto.","Yn gyntaf, beth nad yw AI-gile. Nid cwmni newydd mohono, nid yw ar werth, ac nid oes neb yn casglu dy ddata. Bwrdd rhad ac am ddim ydyw sy'n rhedeg ar dy gyfrifiadur, heb gyfrifon, heb dracwyr a heb gwcis. Beth ydyw: un lle taclus i weld pob prosiect codio AI ar unwaith, gyda thîm o asiantau'n gwneud y cardiau a ti'n gwneud y penderfyniadau. Mae'n plygu cardiau perthnasol at ei gilydd, yn trwsio teitlau dryslyd, ac yn cadw llygad ar ba mor denau mae'r cod yn aros. Mae'n siarad tua 120 o ieithoedd, o Iseldireg a Fflemeg i fôr-leidr a Klingon. Gall ffrindiau anfon neges at ei gilydd, yn breifat ac wedi'i hamgryptio. Fe'i hadeiladwyd gan Rich a nifer fawr o asiantau amyneddgar, gan ddefnyddio ei hun gan amlaf. Mae mewn cyn-alffa caeedig, felly mae'n arw mewn mannau. Os yw'n swnio'n hwyl, gofyn yn gwrtais ac efallai y cei di fynd i mewn yn gynnar."]}],"quips":{"1":"Un gair. Eofn. Efallai'n rhy eofn.","3":"Tri gair. Eisoes yn fwy gonest na'r rhan fwyaf o dudalennau cynnyrch.","8":"Wyth gair. Yn dal yn fyrrach na stand-yp.","21":"Pwyntiau stori yw'r hydoedd, gyda llaw. Wrth gwrs eu bod nhw.","55":"Pum deg pump gair. Gorffennwyd dau gerdyn tra oeddet ti'n darllen hwnna.","144":"Honna yw'r un hir. Does dim 233. Mae'r asiantau wedi mynd i'r gwely."}},"timeline":{"first-idea.name":"Y syniad cyntaf","first-idea.line":"Y sgwrs gyntaf un, cyn bod unrhyw god yn bodoli.","first-board.name":"Y bwrdd cyntaf","first-board.line":"Bwrdd sy'n olrhain ei adeiladu ei hun: cardiau, colofnau, llusgo a gollwng, prosiectau.","team-roles.name":"Tîm a rolau","team-roles.line":"Proffiliau asiantau, templedi tîm, mannau a phwy sy'n gwneud beth.","install.name":"Gosod a fersiynau","install.line":"Zip y gall ffrind ei osod, hunan-ddiweddaru, sianeli a dychwelyd yn ôl.","usage-saver.name":"Arbed defnydd","usage-saver.line":"Mesur beth mae rhediadau'n ei gostio, cadw'r cod yn denau, arbed dy derfyn.","friends.name":"Ffrindiau a rhannu","friends.line":"Negeseuon preifat, cyfnewidfa ddryslyd, gwahoddiadau, rolau a phrosiectau a rennir.","languages.name":"Ieithoedd","languages.line":"Pob testun sgrin mewn ffeil iaith, gydag Iseldireg a Fflemeg yn gyntaf.","ai-tester.name":"Profwr AI","ai-tester.line":"Mae profwr yn gwirio pob trosglwyddiad yn gyntaf ac yn dangos beth a welodd.","website.name":"Y wefan","website.line":"aigile.lol, y rhagflas a'r llinell amser hon.","streaming.name":"Sgwrsio a ffrydio","streaming.line":"Discord, Twitch, OBS, modd ffrydiwr, GIFs ac emojis.","no-ai.name":"Rhifyn Dim AI","no-ai.line":"Bwrdd i bobl sy'n codio heb AI, a byrddau cyhoeddus.","night-watch.name":"Gwylio'r nos","night-watch.line":"Gwyliwr a Scrum Master yn cadw'r timau ar dasg tra byddi di'n cysgu.","p-more.name":"Popeth arall","p-more.line":"Syniadau llai sy'n dal i aros eu tro.","p-android.name":"Ffôn ac Android","p-android.line":"Cyrraedd dy fwrdd o ffôn, yna ap Android brodorol.","p-release.name":"Alffa a thu hwnt","p-release.line":"Alffa caeedig, y wefan fyw, yna beta.","p-languages.name":"Mwy o ieithoedd","p-languages.line":"130 o ieithoedd, a modd trochi i ddysgwyr.","p-engines.name":"Mwy o beiriannau AI","p-engines.line":"Dewisa Claude, Codex, Gemini, Copilot neu Cursor ar gyfer pob asiant.","p-pro.name":"Arfer proffesiynol","p-pro.line":"Labeli risg, pyrth cyfuno, cardiau digwyddiad a rheiliau diogelu.","p-self.name":"Gofalu amdanat ti","p-self.line":"Modd blinedig, nodiadau atgoffa hunanofal a 4:20.","p-servers.name":"Gweinyddion a graddfa","p-servers.line":"Gosodiadau gweinydd byd-eang, rolau a chynllunio ar gyfer twf.","p-livestream.name":"Ychwanegion ffrydio","p-livestream.line":"Sgwrs Twitch, emojis personol a golwg fyw gyhoeddus."},"words":{"button":"📖 Termau arbenigol","h":"📖 Geiriau wedi'u hesbonio","intro":"Y geiriau a weli di yn AI-gile, mewn iaith glir: ei adeiladu, ei newid yn ddiogel, ei gadw i redeg i'r bobl sy'n ei ddefnyddio, a gweithio fel tîm gydag AI.","search":"Chwilio gair…","none":"Dim gair yn cyfateb.","close":"Cau","count":{"one":"{count} gair","other":"{count} gair"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Ei adeiladu"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Ei newid yn ddiogel"},{"id":"run","name":"🛎️ Rhedeg gwasanaeth"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Syniadau a gwaith heb ei gynllunio eto. Does dim byd yno'n cael ei weithio arno nes iddo symud i I'w wneud."},{"id":"sprint","g":"agile","word":"Sprint","text":"Cyfnod byr o waith (wythnos neu ddwy yn aml) gyda set o gardiau y cytunwyd arnyn nhw i'w gorffen.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Cyfarfod cyflym: beth wnaeth pob aelod o'r tîm, beth maen nhw'n ei wneud nesaf, a beth sy'n eu rhwystro.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Bwrdd â cholofnau (I'w wneud, Ar y gweill, Wedi'i wneud) lle mae cardiau'n symud o'r chwith i'r dde wrth i'r gwaith ddigwydd."},{"id":"wip","g":"agile","word":"WIP limit","text":"Gwaith ar y gweill: y nifer fwyaf o gardiau y dylai colofn eu dal, fel bod y tîm yn gorffen pethau cyn dechrau mwy.","also":["WIP"]},{"id":"dod","g":"agile","word":"Diffiniad o Orffenedig","text":"Rhestr wirio fer y tîm o beth mae “gorffenedig” yn ei olygu, fel wedi'i brofi a'i esbonio, cyn i gerdyn gael ei roi i ti. Mae ei efaill, y Diffiniad o Barod, yn dweud pryd mae cerdyn yn ddigon clir i ddechrau.","also":["Diffiniad o Barod","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Golwg yn ôl ar sut mae'r tîm yn gweithio, i gytuno ar un peth i'w wneud yn well. Yn AI-gile mae retro yn awgrymu newid i ffyrdd o weithio'r tîm, ac rwyt ti'n dweud Ewch neu Nid eto.","also":["retros","ôl-sylliad","retrospective"]},{"id":"swarm","g":"agile","word":"Haid","text":"Pawb at y gwaith: mae pob tîm yn gollwng gwaith arall i helpu ar un prosiect brys nes ei fod wedi'i ddatrys. Mae prosiectau eraill yn aros yn y cyfamser.","also":["heidio","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Yr un sy'n cadw'r gwaith i lifo: sylwi ar gardiau sownd, rhoi hwb i'r timau a dy atgoffa o beth sy'n aros. Yn AI-gile mae'r Prif Scrum Master yn gwneud hyn ar draws pob prosiect.","also":["Prif Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Ffolder y prosiect o god a'i hanes llawn o commits, fel arfer wedi'i gadw ar GitHub hefyd.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Llinell waith ar wahân yn y cod, fel y gellir gwneud newidiadau heb gyffwrdd â'r prif fersiwn.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ciplun wedi'i gadw o'r cod, gyda nodyn byr o'r hyn a newidiodd. Gelli di bob amser fynd yn ôl at un.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Anfon cipluniau wedi'u cadw (commits) o'r cyfrifiadur hwn i fyny i GitHub, fel bod copi wrth gefn ohonyn nhw a'u bod yn cael eu rhannu."},{"id":"merge","g":"build","word":"Merge","text":"Uno newidiadau cangen yn ôl i'r prif fersiwn."},{"id":"pr","g":"build","word":"Pull request","text":"Gofyn i newidiadau cangen gael eu gwirio a'u huno â'r prif fersiwn.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tacluso'r cod heb newid beth mae'n ei wneud: ffeiliau llai, enwau cliriach, llai o ailadrodd."},{"id":"bug","g":"build","word":"Bug","text":"Rhywbeth nad yw'n gweithio fel y dylai.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Adolygiad cyfoedion","text":"Ail bâr o lygaid: mae AI arall yn gwirio gwaith pob cerdyn cyn iddo gyrraedd atat ti, fel bod llai o gamgymeriadau'n mynd drwodd.","also":["adolygu cod","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Rhoi cynnig ar ddarn gorffenedig o waith i wirio ei fod yn gwneud yr hyn y gofynnwyd amdano, cyn i ti ei dderbyn.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Byr am quality assurance (sicrhau ansawdd): y gwiriadau awtomatig sy'n rhedeg cyn i unrhyw beth fynd yn fyw. Pan fydd QA yn goch, mae rhywbeth wedi methu, ac ni all fynd yn fyw nes bod hynny wedi'i drwsio.","also":["gwiriadau ansawdd","sicrhau ansawdd","quality checks"]},{"id":"testpile","g":"test","word":"Pentwr profion","text":"Y cardiau gorffenedig sy'n aros i ti roi cynnig arnyn nhw, un ar ôl y llall. Derbyn un neu ei anfon yn ôl gyda nodyn, ac mae'r nesaf yn dod i fyny.","also":["pentyrrau profion","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Rhoi fersiwn newydd yn fyw, er enghraifft ar weinydd lle mae pobl yn ei ddefnyddio."},{"id":"release","g":"change","word":"Datganiad","text":"Bwndel o waith gorffenedig gydag enw, sy'n mynd yn fyw gyda'i gilydd, gyda nodiadau byr ar beth newidiodd. Mae 🚀 Datganiadau yn ysgrifennu'r nodiadau o'r cardiau gorffenedig.","also":["datganiadau","release"]},{"id":"rollback","g":"change","word":"Rholio'n ôl","text":"Mynd yn ôl i'r fersiwn olaf a oedd yn gweithio pan fydd un newydd yn achosi trafferth. Yn AI-gile mae'n gwneud rhestr wirio o'r camau dadwneud sydd wedi'u hysgrifennu ar bob newid.","also":["dadwneud","rollback","roll back"]},{"id":"live","g":"change","word":"Byw","text":"Y fersiwn go iawn y mae pobl yn ei defnyddio, yn hytrach na chopi i roi cynnig ar bethau. Mae datblygwyr hefyd yn ei alw'n production.","also":["yn fyw","cynhyrchu","production","live"],"noTip":1},{"id":"change","g":"change","word":"Newid","text":"Newid wedi'i gynllunio i rywbeth y mae pobl yn dibynnu arno, wedi'i ysgrifennu gyntaf: beth, pam, y risg, pryd, a sut i'w ddadwneud. Dechreua un gyda 🔀 Codi newid.","also":["newidiadau","cais am newid","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risg","text":"Rhywbeth a allai fynd o'i le, wedi'i sgorio ar ba mor debygol a pha mor ddrwg fyddai e. Mae ⚠️ Risgiau yn eu cadw mewn un rhestr, y sgôr uchaf gyntaf, pob un gyda dyddiad i edrych eto.","also":["risgiau","cofrestr risgiau"]},{"id":"chgwin","g":"change","word":"Ffenestr newid","text":"Yr amseroedd pan gaiff newidiadau fynd yn fyw, fel nos Fawrth dawel. Y tu allan i ffenestr does dim modd gorffen cerdyn newid, oni bai ei fod yn argyfwng.","also":["ffenestri newid","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Pleidlais gyflym ychydig cyn i newid fynd yn fyw: mae pob person sy'n gorfod cymeradwyo yn dweud Go neu No go. Dim ond pan fyddan nhw'n cytuno y bydd yn mynd yn ei flaen.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Cymeradwyaeth","text":"Aros am ie cyn i'r gwaith ddechrau. Mae cerdyn y mae ffrind yn ei godi, neu newid, yn aros yn ✅ Cymeradwyaethau nes i ti ei gymeradwyo neu ei wrthod.","also":["cymeradwyaethau","approval"]},{"id":"quiettime","g":"change","word":"Amser tawel","text":"Cyfnod o amser, fel ffrwd, demo neu'r nos, pan nad oes dim yn mynd yn fyw. Mae'r timau'n dal i weithio a phrofi, ond mae mynd yn fyw yn aros nes iddo ddod i ben. Mewn mannau eraill fe'i gelwir yn rhewi newidiadau.","also":["amseroedd tawel","rhewi newidiadau","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Gwasanaeth","text":"Rhywbeth a adeiladaist ti y mae pobl yn dibynnu arno, fel gwefan neu ap, sy'n cael gofal fel ei fod yn dal i weithio. Ticia “Gwasanaeth yw'r prosiect hwn” a dweud beth mae'n ei gynnig, pwy sy'n ei ddefnyddio a phwy sydd ar alwad.","also":["gwasanaethau","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Gwiriad amser i fyny","text":"Gwiriad awtomatig, bob ychydig funudau, fod dy wasanaeth yn dal i ateb. Os yw'n methu sawl gwaith yn olynol, mae AI-gile yn agor cerdyn digwyddiad ar ei ben ei hun.","also":["amser i fyny","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Tudalen statws","text":"Tudalen gyhoeddus sy'n dangos a yw gwasanaeth yn gweithio (gwyrdd, oren neu goch) gyda'r newyddion diweddaraf, fel y gall y bobl sy'n ei ddefnyddio edrych yn lle gofyn.","also":["tudalennau statws","status page"]},{"id":"desk","g":"run","word":"Desg wasanaeth","text":"Lle mae cwestiynau ac adroddiadau gan y bobl sy'n defnyddio dy wasanaeth yn cyrraedd. Mae AI-gile yn trefnu pob un yn gais, yn ddigwyddiad neu'n syniad, ac yn dweud hynny pan mae'n edrych fel rhywbeth sydd eisoes wedi'i adrodd.","also":["desgiau gwasanaeth","desg gymorth","helpdesk"]},{"id":"svcrequest","g":"run","word":"Cais am wasanaeth","text":"Rhywun yn gofyn am rywbeth cyffredin, fel cyfrif newydd neu ychydig o help, yn hytrach na dweud bod rhywbeth wedi torri. Mae'n aros ei dro; mae digwyddiad yn mynd gyntaf.","also":["ceisiadau am wasanaeth"]},{"id":"incident","g":"run","word":"Digwyddiad","text":"Rhywbeth sydd wedi torri i'r bobl sy'n ei ddefnyddio ar hyn o bryd, fel y wefan i lawr. Mae cerdyn 🔥 digwyddiad yn neidio'r ciw: ei gael i weithio eto sy'n dod gyntaf.","also":["digwyddiadau","incident"]},{"id":"major","g":"run","word":"Digwyddiad mawr","text":"Digwyddiad mawr: llawer o bobl wedi'u heffeithio, neu arian neu ddata mewn perygl. Mae un botwm yn rhoi pob tîm arno (haid), yn deffro pwy bynnag sydd ar alwad ac yn gofyn am ddiweddariad statws bob 30 munud.","also":["digwyddiadau mawr","major incident"]},{"id":"oncall","g":"run","word":"Ar alwad","text":"Bod yr un sy'n ateb pan fydd rhywbeth yn torri, hyd yn oed yn y nos. Mae gan bob gwasanaeth aelod o'r tîm ar alwad sy'n cael ei ddeffro gyntaf ar gyfer ei ddigwyddiadau.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Amser ateb","text":"Pa mor hir y gall cerdyn aros am ateb cyntaf, er enghraifft awr ar gyfer digwyddiad. Ar ôl hynny mae'n cael cloc coch, fel nad oes dim yn cael ei anghofio'n dawel. Fe'i gelwir hefyd yn darged ymateb.","also":["amseroedd ateb","targed ymateb","targedau ymateb"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Golwg fer yn ôl ar ôl digwyddiad: beth ddigwyddodd, beth helpodd a beth i'w newid, heb roi'r bai ar neb. Does dim modd cau digwyddiad heb un.","also":["postmortem","adolygiad ar ôl digwyddiad"]},{"id":"problem","g":"run","word":"Problem","text":"Yr achos cudd y tu ôl i un neu fwy o ddigwyddiadau. Mae cerdyn 🧩 problem yn grwpio digwyddiadau sy'n dal i ddod yn ôl, fel bod yr achos yn cael ei ganfod a'i drwsio am byth.","also":["problemau"],"noTip":1},{"id":"rootcause","g":"run","word":"Gwraidd y broblem","text":"Y rheswm go iawn pam y torrodd rhywbeth, nid dim ond yr hyn a welaist ti'n mynd o'i le. Trwsia wraidd y broblem ac mae'r digwyddiad yn peidio â dod yn ôl.","also":["achos sylfaenol","root cause"]},{"id":"workaround","g":"run","word":"Ateb dros dro","text":"Ffordd o gadw pethau i weithio nes bod y trwsiad go iawn yn barod, fel ailgychwyn rhywbeth pan fydd yn mynd yn sownd. Mae wedi'i ysgrifennu ar y cerdyn problem fel nad oes rhaid i neb ei weithio allan eto.","also":["atebion dros dro","workaround"]},{"id":"knownerror","g":"run","word":"Gwall hysbys","text":"Problem y mae ei hachos yn ddealladwy a bod ganddi ateb dros dro, ond sydd heb ei thrwsio eto. Mae 🧩 Gwallau hysbys yn eu rhestru, fel bod pawb yn defnyddio'r ateb dros dro yn lle palu eto.","also":["gwallau hysbys","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Cyfarwyddiadau cam wrth gam i drwsio math hysbys o drafferth, fel ei fod yn cael ei wneud yr un ffordd, yn gyflym, bob tro. Ar ôl digwyddiad mawr gall y tîm gynnig un i ti ei gymeradwyo.","also":["runbooks","llyfr rhedeg"]},{"id":"ci","g":"run","word":"Eitem gyfluniad","text":"Un peth mae dy wasanaeth yn dibynnu arno, fel gweinydd, parth, tystysgrif, allwedd neu gyflenwr. Mae 🗂️ Eitemau cyfluniad yn eu rhestru fesul gwasanaeth, er mwyn i ti weld beth mae digwyddiad yn effeithio arno a beth sydd angen ei adnewyddu neu ei gopïo wrth gefn.","also":["eitemau cyfluniad"]},{"id":"expiry","g":"run","word":"Dyddiad dod i ben","text":"Mae AI-gile yn cadw llygad ar ddyddiadau fel pryd mae tystysgrif neu barth yn dod i ben. O fewn 30 diwrnod i'r dyddiad mae'n gwneud un cerdyn i'w adnewyddu, fel nad oes dim yn stopio gweithio'n annisgwyl.","also":["dyddiadau dod i ben","dod i ben","gwylio dyddiadau dod i ben"]},{"id":"backup","g":"run","word":"Copi wrth gefn","text":"Copi wedi'i gadw o dy ddata o'r blaen, i droi ato os bydd rhywbeth yn mynd ar goll neu'n cael ei ddifrodi. Mae AI-gile yn gwneud copi wrth gefn o dy fyrddau bob dydd.","also":["copïau wrth gefn","backup"]},{"id":"restore","g":"run","word":"Adfer","text":"Rhoi data yn ôl o gopi wrth gefn. Dim ond pan wyddost ti y gellir ei adfer y mae copi wrth gefn yn cyfrif go iawn, felly mae'n werth rhoi cynnig arni bob hyn a hyn.","also":["wedi'i adfer","restore"]},{"id":"svcreview","g":"run","word":"Adolygiad gwasanaeth","text":"Golwg yn ôl ar un mis o wasanaeth: digwyddiadau a agorwyd ac a drwsiwyd, pa mor gyflym cafodd pobl ateb, amser i fyny a'r tocynnau a ddefnyddiwyd. Mae'r Adolygiad misol yn dangos hyn ar gyfer pob gwasanaeth.","also":["adolygiadau gwasanaeth","adolygiad misol","adolygiadau misol"]},{"id":"accessreview","g":"run","word":"Adolygu mynediad","text":"Gwirio bob 90 diwrnod pwy sy'n dal yn gallu mynd i mewn: dolenni rhannu, rolau ffrindiau a chyfrinachau wedi'u cadw. Rwyt ti'n cadw neu'n tynnu pob un, fel nad yw hen fynediad yn aros.","also":["adolygiadau mynediad"]},{"id":"improvements","g":"run","word":"Rhestr welliannau","text":"Popeth mae'r tîm wedi penderfynu gwella arno, mewn un lle: awgrymiadau'r retro, camau o adolygiadau ac atebion i broblemau, pob un gyda'i statws. Mae i'w gweld o dan 📈 Gwelliannau.","also":["rhestrau gwelliannau","gwelliannau"]},{"id":"tokencap","g":"run","word":"Cap tocynnau","text":"Terfyn misol ar y tocynnau mae asiantau gwasanaeth yn cael eu defnyddio. Ar 80% rwyt ti'n cael rhybudd; ar 100% mae eu gwaith cefndir yn aros tan y mis nesaf neu nes i ti godi'r cap.","also":["capiau tocynnau"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI sy'n gweithio ar ei ben ei hun ar dasg: yn darllen y cod, yn gwneud newidiadau, yn rhedeg gwiriadau, ac yn adrodd yn ôl.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Yr uned mae defnydd AI yn cael ei gyfrif ynddi: tua ychydig o lythrennau o destun wedi'u darllen neu eu hysgrifennu. Llai o docynnau, mwy o dy gynllun ar ôl.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Gorchymyn bach sy'n rhedeg ohono'i hun ar adeg benodol, e.e. pan fydd sesiwn AI yn cychwyn, fel bod y tîm yn clywed dy sylwadau.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
